import {renderQuickQuiz} from './quick-quiz.js';
import {libraryPage,alignmentPage,pastpapersPage,lessonResources} from './study-library.js';
import {renderSupplement} from './supplements.js';
import {stopGsatView,gsatLandingPage,gsatExamPage,gsatResultPage} from './gsat-interactive.js';
function exam(){const active=state.active;$('#main').innerHTML=heading('PRACTICE WITH PURPOSE','模擬考場','先練穩，再挑戰計時。所有試卷皆為本站原創練習，不是官方歷屆試題。')+`${active?`<div class="callout row"><div><strong>你有一份未交卷的${active.mode==='exam'?'計時測驗':'練習'}</strong><br>${escape(active.title)} · 已作答 ${Object.keys(active.answers).length}/${active.ids.length} 題</div><a class="button" href="#/quiz">繼續作答 →</a></div>`:''}<div class="panel"><a class="button secondary" href="#/quick">🎲 快速選科 · 10 / 20 題趣味測驗</a><h2>五科會考型模擬</h2><p class="muted">時間與題數落在官方規格範圍，難度與配題為本站設計，尚未經標準化測驗校準。此處涵蓋七至九年級，不受上方年級篩選限制。</p><div class="grid">${examSpecs.map(x=>`<section class="unit-card"><div class="row"><span class="tag">${x.minutes} 分鐘</span><span class="subtle">${x.count} 題${x.id==='math'?'＋2 題非選擇':''}</span></div><h3>${x.name}</h3><p>${x.note}</p><button class="button small" data-exam="${x.id}">進入模擬考 →</button></section>`).join('')}</div><p class="notice">英語聽力使用裝置合成語音，需要裝置提供英文語音；可重播，並非官方一次播放條件。數學非選擇題依規準自行檢核，與選擇題分開呈現。</p></div><section class="panel"><h2>依進度，自訂一份練習</h2><div class="form-row"><label for="exam-subject">科目</label><select id="exam-subject"><option value="all">全科混合</option>${subjects.map(s=>`<option value="${s.id}">${s.name}</option>`).join('')}</select><label for="exam-count">題數上限</label><select id="exam-count"><option>10</option><option>20</option><option>30</option></select><label for="exam-mode">模式</label><select id="exam-mode"><option value="practice">練習・可看提示</option><option value="exam">計時・交卷後看解析</option></select></div><p class="subtle">依上方年級篩選。題目不足時使用現有全部題目，不重複湊題；每題預留 2 分鐘。</p><button id="custom-exam" class="button">產生試卷</button></section><section class="panel"><h2>寫作也是會考的一部分</h2><p>用 50 分鐘完成一篇原創命題作文，依四個向度自評並修訂。</p><a class="button secondary" href="#/writing">進入寫作練習 →</a> <a href="https://cap.rcpet.edu.tw/" target="_blank" rel="noopener" class="source-link">官方歷屆試題與公告 ↗</a></section>`;$$('[data-exam]').forEach(b=>b.onclick=()=>{const spec=examSpecs.find(x=>x.id===b.dataset.exam),pool=spec.id==='listening'?listening:[...questions,...extraQuestions].filter(q=>spec.subjects.includes(q.subject));start(pool,{title:spec.name+'・會考型原創模擬',mode:'exam',count:spec.count,minutes:spec.minutes,constructed:spec.id==='math'?constructed.map(q=>q.id):[]})});$('#custom-exam').onclick=()=>{const selected=$('#exam-subject').value,pool=[...questions,...extraQuestions].filter(q=>(selected==='all'||q.subject===selected)&&(state.grade==='all'||unitById[q.unitId].grade===Number(state.grade))),count=Number($('#exam-count').value);start(pool,{title:(selected==='all'?'全科混合':subjectById[selected].name)+'・自訂練習',mode:$('#exam-mode').value,count,minutes:Math.max(5,Math.min(count,pool.length)*2)})}}
function quiz(){const s=state.active;if(!s)return $('#main').innerHTML=empty('還沒有進行中的練習','選一份適合你的試卷，開始累積解題經驗。','#/exam','選擇試卷');if(remainingSeconds(s)===0){finish(true);return}const id=s.ids[s.cursor],q=bank[id],answer=s.answers[id],revealed=s.mode==='practice'&&s.revealed[id],ordered=s.orders[id];$('#main').innerHTML=`<section class="quiz"><a class="breadcrumb" href="#/exam">← 返回考場（保留作答${s.mode==='exam'?'，計時繼續':''}）</a><div class="quiz-head"><div><span class="tag">${s.mode==='exam'?'計時模式':'練習模式'}</span><h1 style="font-size:1.5rem">${escape(s.title)}</h1></div>${s.deadline?`<div class="timer" id="exam-timer" aria-label="剩餘時間">${formatTime(remainingSeconds(s))}</div>`:'<span class="tag accent">想清楚，比答得快重要</span>'}</div>${s.title.startsWith('趣味闖關・')?`<div class="quick-stars" role="status">★ 理解之星 ${s.ids.filter(id=>s.revealed[id]&&s.answers[id]===bank[id].answer&&!s.hints[id]).length} 顆 · 獨立答對並檢查答案即可收集。<a href="#/quick">選擇下一回合</a></div>`:''}<progress value="${Object.keys(s.answers).length}" max="${s.ids.length}" aria-label="作答進度"></progress><div class="quiz-nav" aria-label="題目導覽">${s.ids.map((qid,i)=>`<button aria-label="第 ${i+1} 題${s.answers[qid]!==undefined?'，已作答':''}" class="${s.answers[qid]!==undefined?'answered ':''}${i===s.cursor?'current':''}" data-question="${i}">${i+1}</button>`).join('')}</div><div class="panel"><div class="row"><span class="tag">${subjectById[q.subject].name} · ${q.difficulty}</span><small class="muted">第 ${s.cursor+1} / ${s.ids.length} 題</small></div>${q.audio?`<div class="callout"><div class="audio-ctrl-row"><button class="button secondary" id="play-audio">▷ 播放英文語音</button><div class="speed-btn-group"><span class="subtle">語速:</span>${[0.8,1.0,1.2].map(r=>`<button type="button" class="speed-btn ${Math.abs((state.audioRate||1.0)-r)<0.05?'active':''}" data-rate="${r}">${r}x</button>`).join('')}</div></div><p class="subtle" id="audio-status">合成語音與官方錄音不同。可依需要調整語速重播；不支援時請使用其他裝置或改做閱讀。</p></div>`:''}<div class="question">${escape(q.prompt)}</div><div class="options" role="group" aria-label="選擇答案">${ordered.map((original,i)=>`<button data-answer="${original}" class="option ${answer===original?'selected ':''}${revealed?(q.answer===original?'correct':answer===original?'wrong':''):''}" aria-pressed="${answer===original}" ${revealed?'disabled':''}><span>${'ABCD'[i]}</span><span>${escape(q.options[original])}</span></button>`).join('')}</div>${s.mode==='practice'?`<div class="actions"><button id="hint" class="button ghost" ${revealed?'disabled':''}>${s.hints[id]?'再看一次提示':'給我一個提示'}</button><button id="check" class="button" ${answer===undefined||revealed?'disabled':''}>檢查這一題</button></div>${s.hints[id]?`<div class="callout"><strong>觀念提示</strong><br>${escape(q.hint)}<p class="subtle">使用提示後，這題會排入回練，不算獨立答對。</p></div>`:''}`:''}${revealed?`<div class="explanation"><strong>${answer===q.answer?'答對了，看看你的推理是否一致。':'先找到卡住的觀念，再試一次。'}</strong><br>正確答案：${escape(q.options[q.answer])}<br>${escape(q.explanation)}${q.audio?'<br>聽力原文：'+escape(q.audio):''}</div>`:''}<div class="actions"><button id="previous-q" class="button secondary" ${s.cursor===0?'disabled':''}>← 上一題</button>${s.cursor<s.ids.length-1?'<button id="next-q" class="button">下一題 →</button>':''}<button id="submit-quiz" class="button ${s.cursor===s.ids.length-1?'':'secondary'}">交卷與檢討</button></div><p class="subtle">已作答 ${Object.keys(s.answers).length} / ${s.ids.length} 題。作答即時儲存於本機${s.mode==='exam'?'；重新整理或離開頁面不會暫停計時':''}。</p></div>${s.constructed.length?`<section class="panel"><h2>非選擇題 · 寫下你的推理</h2><p class="muted">共 2 題，與選擇題共用 80 分鐘。交卷後提供參考解法與自評規準，不自動折算會考分數。</p>${s.constructed.map(cid=>{const c=constructed.find(x=>x.id===cid);return `<h3>${c.title}</h3><p class="evidence">${escape(c.prompt)}</p><label for="work-${cid}" class="subtle">我的解題過程與答案</label><textarea id="work-${cid}" data-work="${cid}">${escape(s.work[cid]||'')}</textarea>`}).join('')}</section>`:''}</section>`;
 $$('[data-answer]').forEach(b=>b.onclick=()=>{if(s.revealed[id]&&s.mode==='practice')return;s.answers[id]=Number(b.dataset.answer);save();quiz()});$$('[data-question]').forEach(b=>b.onclick=()=>{stopAudio();s.cursor=Number(b.dataset.question);save();quiz()});$$('[data-rate]').forEach(b=>b.onclick=()=>{state.audioRate=Number(b.dataset.rate);save();quiz()});$('#previous-q').onclick=()=>{stopAudio();s.cursor--;save();quiz()};if($('#next-q'))$('#next-q').onclick=()=>{stopAudio();s.cursor++;save();quiz()};if($('#hint'))$('#hint').onclick=()=>{s.hints[id]=true;save();quiz()};if($('#check'))$('#check').onclick=()=>{s.revealed[id]=true;save();quiz()};$('#submit-quiz').onclick=()=>confirmFinish();$$('[data-work]').forEach(t=>t.oninput=()=>{s.work[t.dataset.work]=t.value;save()});if($('#play-audio'))$('#play-audio').onclick=()=>speak(q.audio,state.audioRate);startTimer();
}
function stopAudio(){if('speechSynthesis' in window)window.speechSynthesis.cancel()}
function speak(text,rate=state.audioRate||1.0){if(!('speechSynthesis' in window)){toast('此瀏覽器沒有合成語音功能，請改用支援的裝置。');return}stopAudio();const utterance=new SpeechSynthesisUtterance(text);utterance.lang='en-US';utterance.rate=rate;const voice=window.speechSynthesis.getVoices().find(v=>v.lang.startsWith('en'));if(voice)utterance.voice=voice;utterance.onstart=()=>{if($('#audio-status'))$('#audio-status').textContent=`正在播放英文語音 (${rate}x)…`};utterance.onend=()=>{if($('#audio-status'))$('#audio-status').textContent='播放完成。可以再次播放。'};utterance.onerror=()=>{if($('#audio-status'))$('#audio-status').textContent='英文語音無法播放，請確認裝置語音設定。';toast('語音播放失敗，請確認英文語音可用。')};window.speechSynthesis.speak(utterance)}
function startTimer(){clearInterval(timer);if(!state.active?.deadline)return;timer=setInterval(()=>{const s=state.active;if(!s)return clearInterval(timer);const left=remainingSeconds(s);if($('#exam-timer'))$('#exam-timer').textContent=formatTime(left);if(left===0)finish(true)},1000)}
async function confirmFinish(){const s=state.active,unanswered=s.ids.length-Object.keys(s.answers).length,incomplete=s.constructed.filter(id=>!s.work[id]?.trim()).length;if(await ask('確認交卷？',`尚有 ${unanswered} 題選擇題${incomplete?'、'+incomplete+' 題非選擇題':''}未作答。交卷後將顯示答案與解析，並更新學習紀錄。`,'交卷'))finish(false)}
function finish(expired){const s=state.active;if(!s||s.submitted)return;s.submitted=true;stopAudio();clearInterval(timer);const score=gradeSession(s,bank);for(const row of score.rows)state.records[row.id]=nextRecord(state.records[row.id],row.correct,row.hinted);activity();const result={id:s.id,title:s.title,mode:s.mode,at:Date.now(),duration:Math.max(0,Math.min(Date.now()-s.started,s.deadline?s.deadline-s.started:Infinity)),...score,expired,work:s.work,constructed:s.constructed};state.history.unshift(result);state.history=state.history.slice(0,100);state.active=null;save();location.hash='#/result/'+result.id;if(lastRoute==='/result/'+result.id)render();if(expired)toast('時間已到，已自動交卷。')}
function result(id){const r=state.history.find(x=>x.id===id);if(!r)return notFound();const wrongRows=r.rows.filter(x=>!x.correct||x.hinted);$('#main').innerHTML=heading('REFLECT & IMPROVE','每一道錯題，都是下一步的線索。',escape(r.title))+`<div class="panel"><div class="row"><div><span class="result-score">${r.correct}<small> / ${r.total}</small></span><p class="muted">選擇題答對率 ${r.percent}% · 獨立答對 ${r.independent} 題</p></div><div><span class="tag">${r.expired?'時間到自動交卷':'已完成交卷'}</span><p class="subtle">作答 ${formatTime(Math.floor(r.duration/1000))} · ${date(r.at)}</p></div></div><p class="notice">這是本站原創卷的答對率，不能直接換算 A++、官方等級或預測正式成績。非選擇題與寫作未合併計分。</p><div class="actions">${wrongRows.length?'<button id="retry-wrong" class="button">針對待補強題再練一次</button>':''}<a class="button secondary" href="#/review">查看複習安排</a><a class="button ghost" href="#/exam">選擇下一份練習</a><a class="button secondary" href="#/quick">🎲 再抽一回趣味測驗</a></div></div><h2>逐題檢討</h2>${r.rows.map((row,i)=>{const q=bank[row.id];return `<details ${!row.correct?'open':''}><summary>${row.correct?'✓':'○'} 第 ${i+1} 題 · ${unitById[q.unitId].title}${row.hinted?' · 使用過提示':''}</summary><p class="evidence">${escape(q.prompt)}</p><p>你的答案：${row.answer===null?'未作答':escape(q.options[row.answer])}<br><strong>正確答案：${escape(q.options[q.answer])}</strong></p><div class="explanation">${escape(q.explanation)}${q.audio?'\n聽力原文：'+escape(q.audio):''}</div><div class="actions"><a class="button small secondary" href="#/lesson/${q.unitId}">回到觀念講解 →</a></div></details>`}).join('')}${r.constructed?.length?`<h2 style="margin-top:28px">非選擇題 · 參考解法與自評</h2>${r.constructed.map(cid=>{const c=constructed.find(x=>x.id===cid);return `<section class="panel"><h3>${c.title}</h3><p class="evidence">${escape(c.prompt)}</p><h3>你的作答</h3><p class="evidence">${escape(r.work[cid]||'未作答')}</p><div class="example">${escape(c.solution)}</div>${c.rubric.map(text=>`<label class="check"><input type="checkbox">${text}</label>`).join('')}<p class="subtle">此處勾選僅供當下自評。請教師確認推理、步驟與等價解法。</p></section>`}).join('')}`:''}`;if($('#retry-wrong'))$('#retry-wrong').onclick=()=>start(wrongRows.map(x=>bank[x.id]),{title:'錯題與提示題・回練',count:wrongRows.length})}
function review(){const ids=[...new Set([...wrong(),...due()])],filtered=ids.filter(id=>state.grade==='all'||unitById[bank[id].unitId].grade===Number(state.grade));$('#main').innerHTML=heading('SPACED PRACTICE','把不熟的，練成自己的。','答錯或使用提示的題目，隔一天再回想；獨立答對後，間隔逐步延長。')+`<div class="stats">${stat(wrong().length,'待補強','含錯答、未答與提示題')}${stat(due().length,'到期複習','到期後重新提取記憶')}${stat(Object.values(state.records).filter(r=>r.streak>=2).length,'跨日獨立答對','至少兩個不同日子答對')}${stat(Object.keys(state.records).length,'累積練習題','不同題目，不重複灌水')}</div>${filtered.length?`<div class="actions"><button id="review-start" class="button">開始回練 · ${Math.min(filtered.length,15)} 題</button><span class="subtle">依目前年級顯示 ${filtered.length} 題</span></div><div class="stack">${filtered.map(id=>{const q=bank[id],r=state.records[id];return `<section class="panel"><div class="row"><span class="tag">${subjectById[q.subject].name}</span><small class="muted">${!r.latestCorrect?'待補強':'到期複習'} · 累計 ${r.attempts} 次</small></div><h3>${unitById[q.unitId].title}</h3><p>${escape(q.prompt.slice(0,130))}${q.prompt.length>130?'…':''}</p><div class="actions"><button class="button small" data-retry="${id}">單題回練</button><a class="button small secondary" href="#/lesson/${q.unitId}">先看觀念</a></div></section>`}).join('')}</div>`:empty('目前沒有需要處理的複習題','完成練習後，依真實作答安排下一次複習。若有其他年級錯題，可切換全部年級。','#/exam','開始一次練習')}<div class="panel"><h2>複習規則，清楚看得見</h2><p class="notice">本站採固定間隔啟發式：跨日獨立答對後，安排 1、3、7、14 天；答錯或看提示會回到 1 天。同一天重做不增加跨日連續次數。這是複習輔助，不是經校準的能力診斷。</p></div>`;if($('#review-start'))$('#review-start').onclick=()=>start(filtered.map(id=>bank[id]),{title:'間隔複習',count:15});$$('[data-retry]').forEach(b=>b.onclick=()=>start([bank[b.dataset.retry]],{title:'單題回練',count:1}))}
function progress(){const records=Object.values(state.records);$('#main').innerHTML=heading('YOUR PROGRESS','進步，來自每一次認真理解。','這裡只記錄你的實際學習，不用別人的速度定義自己。')+`<div class="stats">${stat(state.days.length,'累積學習日','不因休息而扣分')}${stat(state.read.length,'已閱讀主題',`全站 ${units.length} 個主題`)}${stat(state.bookmarks.length,'我的收藏','點選星號快速收藏重點')}${stat(records.filter(r=>r.latestCorrect).length,'最近獨立答對','需持續跨情境驗證')}</div><section class="panel"><div class="row"><h2>各科練習足跡</h2><button id="export-data" class="button small secondary">匯出本機學習備份</button></div><div class="table-wrap"><table><thead><tr><th>科目</th><th>已閱讀</th><th>已練習題</th><th>最近獨立答對</th><th>下一步</th></tr></thead><tbody>${subjects.map(s=>{const us=units.filter(u=>u.subject===s.id),qs=allQuestions.filter(q=>q.subject===s.id),p=pct(qs);return `<tr><td>${s.name}</td><td>${us.filter(u=>state.read.includes(u.id)).length}/${us.length}</td><td>${p.attempted}/${qs.length}</td><td>${p.correct} 題</td><td><a class="source-link" href="#/subject/${s.id}">前往學習</a></td></tr>`}).join('')}</tbody></table></div><p class="notice">資料只存在此瀏覽器，不會跨裝置同步。清除瀏覽資料會移除紀錄。匯出包含你的筆記與作文，請自行保管。</p></section><section class="panel"><h2>最近的測驗</h2>${state.history.length?`<div class="table-wrap"><table><thead><tr><th>日期</th><th>練習</th><th>答對題數</th><th>檢討</th></tr></thead><tbody>${state.history.slice(0,20).map(r=>`<tr><td>${date(r.at)}</td><td>${escape(r.title)}</td><td>${r.correct}/${r.total}</td><td><a class="source-link" href="#/result/${r.id}">看解析 →</a></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">還沒有交卷紀錄，完成一次練習就會出現在這裡。</p>'}</section><section class="panel"><h2>實作與表達紀錄</h2>${Object.keys(state.notes).filter(id=>state.notes[id]?.trim()).length?Object.keys(state.notes).filter(id=>state.notes[id]?.trim()&&unitById[id]).map(id=>`<details><summary>${unitById[id].title}</summary><p class="evidence">${escape(state.notes[id])}</p><a class="source-link" href="#/lesson/${id}">返回修改</a></details>`).join(''):'<p class="muted">在各單元留下觀察、推理或作品說明，就能回顧自己的思考。</p>'}</section>`;$('#export-data').onclick=()=>download('知行學院-學習備份-'+today()+'.json',JSON.stringify(state,null,2),'application/json')}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function writing(){const index=Number(new URLSearchParams(location.hash.split('?')[1]||'').get('prompt')||0),selected=Number.isInteger(index)&&index>=0&&index<writingPrompts.length?index:0,prompt=writingPrompts[selected],draft=state.writing[selected]||{text:'',checks:{},deadline:null};state.writing[selected]=draft;$('#main').innerHTML=heading('FIND YOUR VOICE','寫出你的觀點，也寫出理由。','原創命題寫作 · 50 分鐘練習 · 儲存草稿、檢核、再修訂')+`<section class="panel"><label for="writing-prompt">選擇題目</label><select id="writing-prompt">${writingPrompts.map((p,i)=>`<option value="${i}" ${i===selected?'selected':''}>${p.title}</option>`).join('')}</select><h2 style="margin-top:24px">${prompt.title}</h2><p>${prompt.lead}</p><div class="callout"><strong>先想清楚這幾件事</strong><ol>${prompt.plan.map(x=>`<li>${x}</li>`).join('')}</ol></div><div class="actions"><button class="button secondary" id="writing-timer">${draft.deadline?'重新設定 50 分鐘':'開始 50 分鐘練習'}</button><span id="writing-time" class="timer">${draft.deadline?formatTime(Math.max(0,Math.ceil((draft.deadline-Date.now())/1000))):'50:00'}</span></div><label for="writing-text">我的作文</label><textarea id="writing-text" style="min-height:440px" placeholder="先完成一稿，再回頭調整結構與用字。">${escape(draft.text)}</textarea><div class="row"><p id="writing-status" class="subtle">${draft.text.replace(/\s/g,'').length} 字元 · 本機草稿</p><button id="export-writing" class="button small secondary">下載作文文字</button></div><p class="notice">字元數包含標點，僅供參考，不以字數判定級分。時間到保留草稿，可繼續修訂。</p></section><section class="panel"><h2>用四個向度，做一次有方向的修訂</h2>${['立意取材：我回應題目，並用具體事件或細節支持觀點。','結構組織：段落有清楚順序，轉折與結尾能呼應主題。','遣詞造句：用詞貼切，句子通順，避免空泛堆砌。','錯別字、格式與標點：我已逐句檢查，並完成一次朗讀。'].map((t,i)=>`<label class="check"><input type="checkbox" data-writing-check="${i}" ${draft.checks?.[i]?'checked':''}>${t}</label>`).join('')}<p class="notice">本站不依關鍵字或字數自動宣稱六級分。正式寫作需由評閱者依整體表現評定；建議請教師提供回饋。</p></section>`;$('#writing-prompt').onchange=e=>location.hash='#/writing?prompt='+e.target.value;$('#writing-text').oninput=e=>{draft.text=e.target.value;activity();save();$('#writing-status').textContent=draft.text.replace(/\s/g,'').length+' 字元 · '+(storageOK?'已儲存':'儲存受限，請下載備份')};$('#writing-timer').onclick=async()=>{if(draft.deadline&&draft.deadline>Date.now()&&!await ask('重新開始計時？','作文內容保留，倒數會回到 50 分鐘。','重新計時'))return;draft.deadline=Date.now()+50*60000;save();writing()};$$('[data-writing-check]').forEach(c=>c.onchange=()=>{draft.checks={...draft.checks,[c.dataset.writingCheck]:c.checked};save()});$('#export-writing').onclick=()=>download(prompt.title+'.txt',prompt.title+'\n\n'+draft.text,'text/plain;charset=utf-8');clearInterval(writing.timer);writing.timer=setInterval(()=>{if(!$('#writing-time'))return clearInterval(writing.timer);if(draft.deadline){const left=Math.max(0,Math.ceil((draft.deadline-Date.now())/1000));$('#writing-time').textContent=formatTime(left);if(!left){clearInterval(writing.timer);toast('50 分鐘已到，草稿保留，可以開始檢核與修訂。')}}},1000)}
