try{const data=JSON.parse(localStorage.getItem(KEY));if(data?.version===1){state={...state,...data};for(const key of ['read','history','days','bookmarks'])if(!Array.isArray(state[key]))state[key]=[];for(const key of ['notes','portfolio','records','writing'])if(!state[key]||typeof state[key]!=='object'||Array.isArray(state[key]))state[key]={};if(typeof state.audioRate!=='number'||state.audioRate<=0)state.audioRate=1.0;if(state.active&&(!Array.isArray(state.active.ids)||state.active.ids.some(id=>!bank[id])))state.active=null;}}catch{storageOK=false}
