let printDetails=[];
window.addEventListener('beforeprint',()=>{printDetails=[...document.querySelectorAll('.case-solution:not([open])')];printDetails.forEach(el=>el.open=true)});
window.addEventListener('afterprint',()=>{printDetails.forEach(el=>el.open=false);printDetails=[]});
